struct PS_IN { float4 pos : SV_Position; float2 uv : TEXCOORD0; };

float4 main(PS_IN In) : SV_Target0
{
    float node3_out = g_params[0].x;
    float node4_out = g_params[1].x;
    float2 bloom2_tx = float2(1.0/1280.0, 1.0/720.0) * (node4_out);
    float3 bloom2_sum = float3(0,0,0);
    float bloom2_wsum = 0.0;
    [unroll] for (int bloom2_y = -4; bloom2_y <= 4; ++bloom2_y)
    [unroll] for (int bloom2_x = -4; bloom2_x <= 4; ++bloom2_x)
    {
        float2 bloom2_o = float2(bloom2_x, bloom2_y) * bloom2_tx;
        float bloom2_w = exp(-(bloom2_x*bloom2_x + bloom2_y*bloom2_y) * 0.15);
        float3 bloom2_c = g_input0.Sample(g_sampler, In.uv + bloom2_o).rgb;
        float bloom2_lum = dot(bloom2_c, float3(0.299, 0.587, 0.114));
        float bloom2_bright = max(bloom2_lum - (node3_out), 0.0);
        float3 bloom2_contrib = bloom2_c * (bloom2_bright / max(bloom2_lum, 0.001));
        bloom2_sum += bloom2_contrib * bloom2_w;
        bloom2_wsum += bloom2_w;
    }
    float3 bloom2_result = bloom2_sum / max(bloom2_wsum, 0.001);
    float4 node2_out = float4(bloom2_result, 1.0);
    return node2_out;
}

