struct PS_IN { float4 pos : SV_Position; float2 uv : TEXCOORD0; };

float4 main(PS_IN In) : SV_Target0
{
    float3 bcomp3_bloom = g_input0.Sample(g_sampler, In.uv).rgb;
    float4 sceneSample = g_input1.Sample(g_sampler, In.uv);
    float3 bcomp3_scene = sceneSample.rgb;
    float node4_out = g_params[0].x;
    float3 bcomp3_result = bcomp3_scene + bcomp3_bloom * (node4_out);
    float4 node3_out = float4(bcomp3_result, 1.0);
    return node3_out;
}

