float filmHash(float2 p)
{
    return frac(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}


struct PS_IN { float4 pos : SV_Position; float2 uv : TEXCOORD0; };

float4 main(PS_IN In) : SV_Target0
{
    float node3_out = g_params[0].x;
    float node4_out = g_params[1].x;
    float node5_out = g_params[2].x;
    float node6_out = g_params[3].x;
    float node7_out = g_params[4].x;
    float node8_out = g_params[5].x;
    float2 film2_center = In.uv - 0.5;
    float film2_ab = (node3_out) * 0.01;
    float2 film2_dir = film2_center * film2_ab;
    float film2_r = g_input0.Sample(g_sampler, In.uv + film2_dir).r;
    float film2_g = g_input0.Sample(g_sampler, In.uv).g;
    float film2_b = g_input0.Sample(g_sampler, In.uv - film2_dir).b;
    float3 film2_col = float3(film2_r, film2_g, film2_b);
    float2 film2_texel = float2(1.0/1280.0, 1.0/720.0);
    float3 film2_bl = (g_input0.Sample(g_sampler, In.uv - float2(film2_texel.x,0)).rgb
                    + g_input0.Sample(g_sampler, In.uv + float2(film2_texel.x,0)).rgb
                    + g_input0.Sample(g_sampler, In.uv - float2(0,film2_texel.y)).rgb
                    + g_input0.Sample(g_sampler, In.uv + float2(0,film2_texel.y)).rgb) * 0.25;
    film2_col += (film2_col - film2_bl) * (node6_out);
    float film2_lum = dot(film2_col, float3(0.299,0.587,0.114));
    float film2_mx = max(film2_col.r, max(film2_col.g, film2_col.b));
    float film2_mn = min(film2_col.r, min(film2_col.g, film2_col.b));
    float film2_boost = (node7_out) * (1.0 - (film2_mx - film2_mn));
    film2_col = lerp(film2_lum.xxx, film2_col, 1.0 + film2_boost);
    float film2_gr = (filmHash(In.uv + frac(g_time)) - 0.5) * (node4_out);
    film2_col += film2_gr;
    float film2_vig = 1.0 - length(film2_center) * (node5_out);
    film2_vig = saturate(film2_vig);
    film2_col *= film2_vig;
    film2_col += (filmHash(In.uv * 1.7) - 0.5) * (node8_out) / 255.0;
    float4 node2_out = float4(film2_col, 1.0);
    return node2_out;
}
